import java.util.*;

class Solution {
  public List<Integer> arraysIntersection(int[] arr1, int[] arr2, int[] arr3) {
    List<Integer> res = new ArrayList<>();
    for (int i = 0, j = 0, k = 0; i < arr1.length && j < arr2.length && k < arr3.length; ) {
      int a = arr1[i], b = arr2[j], c = arr3[k];
      if (a == b && b == c) {
        res.add(a);
        i++;
        j++;
        k++;
      } else {
        int max = Math.max(a, Math.max(b, c)); // advance everything smaller than the largest head
        if (a < max) i++;
        if (b < max) j++;
        if (c < max) k++;
      }
    }
    return res;
  }
}
